def t(key: str, locale: str = "fr") -> str:
    entry = STRINGS.get(key)
    if not entry:
        return key
    return entry.get(locale) or entry.get("fr") or key


def locale_name(locale: str) -> str:
    return LANGUAGES.get(locale, LANGUAGES["fr"])["label"]


def direction(locale: str) -> str:
    return LANGUAGES.get(locale, LANGUAGES["fr"])["dir"]
